return ['domain'=>'paginova','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de_DE','project-id-version'=>'Paginova 2.2.0','pot-creation-date'=>'2026-11-13T12:54:45+00:00','po-revision-date'=>'2026-11-07 20:54+0000','x-generator'=>'GNU gettext msgmerge + reviewed translations','messages'=>['Paginova – Chapters for Long Posts'=>'Paginova – Kapitel für lange Beiträge','https://github.com/PaulArgoud/paginova'=>'https://github.com/PaulArgoud/paginova','Split long posts into chapters, each on its own page with its own URL and title, with a table of contents and chapter navigation. Works with the block editor and the classic editor. Formerly Post Chapters, successor of Multipage.'=>'Teile lange Beiträge in Kapitel auf, jedes auf einer eigenen Seite mit eigener URL und eigenem Titel, mit Inhaltsverzeichnis und Kapitelnavigation. Funktioniert mit dem Block-Editor und dem klassischen Editor. Früher Post Chapters, Nachfolger von Multipage.','Paul ARGOUD, based on Multipage by SGr33n (aka Sergio De Falco, Envire Web Solutions).'=>'Paul ARGOUD, basierend auf Multipage von SGr33n (alias Sergio De Falco, Envire Web Solutions).','https://paul.argoud.net'=>'https://paul.argoud.net','Intro'=>'Einleitung','Chapter %d'=>'Kapitel %d','Chapter %'=>'Kapitel %','Chapter navigation'=>'Kapitelnavigation','Table of contents'=>'Inhaltsverzeichnis','Paginova Options'=>'Optionen von Paginova','Paginova'=>'Paginova','Paginova Advanced Settings'=>'Erweiterte Einstellungen von Paginova','Settings'=>'Einstellungen','chapter'=>'Kapitel','Start a new chapter'=>'Neues Kapitel beginnen','Enter the chapter title'=>'Gib den Titel des Kapitels ein','Last rebuilt: %s.'=>'Zuletzt neu aufgebaut: %s.','Last rebuilt: unknown date.'=>'Zuletzt neu aufgebaut: Datum unbekannt.','The chapter index has never been rebuilt on this site.'=>'Der Kapitelindex wurde auf dieser Website noch nie neu aufgebaut.','Chapter index'=>'Kapitelindex','Paginova stores the list of chapters of each post when the post is saved. Rebuild this index after an update, an import, or if the table of contents of a post looks out of date. Posts are processed in batches; on large sites the remaining posts are processed in the background.'=>'Paginova speichert beim Speichern eines Beitrags die Liste seiner Kapitel. Baue diesen Index nach einem Update oder einem Import neu auf oder wenn das Inhaltsverzeichnis eines Beitrags veraltet wirkt. Die Beiträge werden stapelweise verarbeitet; bei großen Websites werden die verbleibenden Beiträge im Hintergrund verarbeitet.','A rebuild is in progress in the background: %s post checked so far.'=>'Im Hintergrund läuft ein Neuaufbau: bisher wurde %s Beitrag geprüft.' . "\0" . 'Im Hintergrund läuft ein Neuaufbau: bisher wurden %s Beiträge geprüft.','Rebuild chapter index'=>'Kapitelindex neu aufbauen','Sorry, you are not allowed to manage options for this site.'=>'Du hast leider nicht die Berechtigung, Optionen für diese Website zu verwalten.','%s post checked'=>'%s Beitrag geprüft' . "\0" . '%s Beiträge geprüft','%s post updated'=>'%s Beitrag aktualisiert' . "\0" . '%s Beiträge aktualisiert','%s stale entry removed'=>'%s veralteter Eintrag entfernt' . "\0" . '%s veraltete Einträge entfernt','Chapter index rebuilt: %1$s, %2$s, %3$s.'=>'Kapitelindex neu aufgebaut: %1$s, %2$s, %3$s.','Chapter index rebuild started: %1$s, %2$s, %3$s so far. The remaining posts are processed in the background.'=>'Neuaufbau des Kapitelindex gestartet: bisher %1$s, %2$s, %3$s. Die verbleibenden Beiträge werden im Hintergrund verarbeitet.','A chapter index rebuild is already running. Please try again in a few minutes.'=>'Ein Neuaufbau des Kapitelindex läuft bereits. Bitte versuche es in ein paar Minuten erneut.','Paginova Settings'=>'Einstellungen von Paginova','Paginova settings sections'=>'Bereiche der Einstellungen von Paginova','Advanced'=>'Erweitert','Advanced Settings'=>'Erweiterte Einstellungen','Please leave this settings to their default values, change only if you really know what to do.'=>'Bitte belasse diese Einstellungen auf ihren Standardwerten und ändere sie nur, wenn du genau weißt, was du tust.','Save Settings'=>'Einstellungen speichern','Options'=>'Optionen','Custom (%s)'=>'Individuell (%s)','Main Settings'=>'Allgemeine Einstellungen','Pagination'=>'Seitennummerierung','Hide the default intro title'=>'Standardtitel der Einleitung ausblenden','Display comments on'=>'Kommentare anzeigen auf','Navigation type'=>'Art der Navigation','Disable the standard pagination'=>'Standard-Seitennummerierung deaktivieren','Disable the WordPress standard pagination'=>'Standard-Seitennummerierung von WordPress deaktivieren','By default, WordPress displays a pagination with only numbers on posts split into pages. Uncheck this if you still want this standard pagination to be displayed.'=>'Standardmäßig zeigt WordPress bei Beiträgen, die in Seiten aufgeteilt sind, eine Seitennummerierung an, die nur aus Zahlen besteht. Deaktiviere diese Option, wenn diese Standard-Seitennummerierung trotzdem angezeigt werden soll.','Only on the first page'=>'Nur auf der ersten Seite','Display the table of contents only on the first page of the post'=>'Inhaltsverzeichnis nur auf der ersten Seite des Beitrags anzeigen','Position'=>'Position','Row labels'=>'Zeilenbeschriftungen','Hide header'=>'Überschrift ausblenden','Hide the table of contents header'=>'Überschrift des Inhaltsverzeichnisses ausblenden','Comments link'=>'Link zu den Kommentaren','Add a link for the comments inside the table of contents'=>'Im Inhaltsverzeichnis einen Link zu den Kommentaren hinzufügen','If comments are enabled, this will display, inside the table of contents, a link for the comments list.'=>'Wenn Kommentare aktiviert sind, wird im Inhaltsverzeichnis ein Link zur Liste der Kommentare angezeigt.','Rewrite Title Priority'=>'Priorität für das Umschreiben des Titels','Some plugins need this higher in order to correctly show the chapter title instead of "Page # of #". If the title works good please leave this to normal.'=>'Einige Plugins benötigen hier einen höheren Wert, damit statt „Seite # von #“ der Titel des Kapitels korrekt angezeigt wird. Wenn der Titel richtig angezeigt wird, belasse diesen Wert bitte auf „Normal“.','Rewrite Content Priority'=>'Priorität für das Umschreiben des Inhalts','This value affects the position where the table of contents is displayed, referring to other plugins that use <code><a href="%1$s" target="_blank">the_content</a></code> filter. e.g. above or below social buttons or related posts. If the table of contents position looks good please leave this to normal.'=>'Dieser Wert bestimmt die Position des Inhaltsverzeichnisses im Verhältnis zu anderen Plugins, die den Filter <code><a href="%1$s" target="_blank">the_content</a></code> verwenden, z. B. ober- oder unterhalb von Social-Media-Buttons oder ähnlichen Beiträgen. Wenn die Position des Inhaltsverzeichnisses passt, belasse diesen Wert bitte auf „Normal“.','Disable TinyMCE Buttons'=>'TinyMCE-Buttons deaktivieren','Disable the TinyMCE Chapter button in the classic editor. Leave unchecked unless you experience editor conflicts.'=>'Deaktiviert den TinyMCE-Button „Kapitel“ im klassischen Editor. Lass diese Option deaktiviert, sofern keine Konflikte mit dem Editor auftreten.','Highest'=>'Sehr hoch','High'=>'Hoch','Normal'=>'Normal','Low'=>'Niedrig','Lowest'=>'Sehr niedrig','All pages — Display comments on all post pages'=>'Alle Seiten — Kommentare auf allen Seiten des Beitrags anzeigen','First page — Display comments only on the first page'=>'Erste Seite — Kommentare nur auf der ersten Seite anzeigen','Last page — Display comments only on the last page'=>'Letzte Seite — Kommentare nur auf der letzten Seite anzeigen','Continue or back to intro'=>'Weiter oder zurück zur Einleitung','Next and previous'=>'Weiter und zurück','Hidden'=>'Ausgeblendet','above the post content, align left'=>'über dem Beitragsinhalt, linksbündig','above the post content, align right'=>'über dem Beitragsinhalt, rechtsbündig','above the post content'=>'über dem Beitragsinhalt','below the post content'=>'unter dem Beitragsinhalt','hidden'=>'ausgeblendet','number — Display numbers before the chapter title'=>'Nummer — Nummer vor dem Titel des Kapitels anzeigen','chapter # — Display "Chapter #" before the chapter title'=>'Kapitel # — „Kapitel #“ vor dem Titel des Kapitels anzeigen','hidden — Hide the labels, display only the chapter title'=>'ausgeblendet — Beschriftungen ausblenden, nur den Titel des Kapitels anzeigen','An invalid value was submitted for the %s setting. The previous value was kept.'=>'Für die Einstellung %s wurde ein ungültiger Wert übermittelt. Der bisherige Wert wurde beibehalten.','Next page'=>'Nächste Seite','Previous page'=>'Vorherige Seite','Continue: %s'=>'Weiter: %s','Back to: %s'=>'Zurück zu: %s','Comments'=>'Kommentare','Contents'=>'Inhalt','Paginova is not running yet.'=>'Paginova ist noch nicht aktiv.','Deactivate Post Chapters: Paginova is its new name and takes over its settings and content.'=>'Deaktiviere Post Chapters: Paginova ist sein neuer Name und übernimmt seine Einstellungen und Inhalte.','To remove Post Chapters afterwards, delete its folder from the server rather than from the Plugins screen: deleting it from the Plugins screen erases the settings and the chapter index that Paginova uses.'=>'Um Post Chapters anschließend zu entfernen, lösche seinen Ordner auf dem Server statt über die Plugin-Seite: Das Löschen über die Plugin-Seite entfernt die Einstellungen und den Kapitelindex, die Paginova verwendet.','Deactivate Multipage: Paginova replaces it and takes over its settings and content.'=>'Deaktiviere Multipage: Paginova ersetzt es und übernimmt seine Einstellungen und Inhalte.','To remove Multipage afterwards, delete its folder from the server rather than from the Plugins screen: Multipage 1.5.15 and later erase, when deleted from the Plugins screen, the settings and the chapter index that Paginova uses.'=>'Um Multipage anschließend zu entfernen, lösche seinen Ordner auf dem Server statt über die Plugin-Seite: Beim Löschen über die Plugin-Seite entfernen Multipage 1.5.15 und neuer die Einstellungen und den Kapitelindex, die Paginova verwendet.','Write chapter title…'=>'Titel des Kapitels eingeben …','%d heading turned into a chapter. You can undo it.'=>'%d Überschrift wurde in ein Kapitel verwandelt. Du kannst das rückgängig machen.' . "\0" . '%d Überschriften wurden in Kapitel verwandelt. Du kannst das rückgängig machen.','Untitled chapter'=>'Kapitel ohne Titel','Chapters'=>'Kapitel','No chapters yet. Add a Chapter block where a chapter starts, or turn headings into chapters.'=>'Noch keine Kapitel. Füge dort, wo ein Kapitel beginnt, einen Kapitel-Block ein oder verwandle Überschriften in Kapitel.','Heading level'=>'Überschriftenebene','Only the headings at the top level of the post.'=>'Nur Überschriften auf der obersten Ebene des Beitrags.','Turn %d heading into a chapter'=>'%d Überschrift in ein Kapitel verwandeln' . "\0" . '%d Überschriften in Kapitel verwandeln','No heading of this level'=>'Keine Überschrift dieser Ebene','block titleChapter'=>'Kapitel','block descriptionStart a new chapter: split your post into pages, each with its own title.'=>'Beginne ein neues Kapitel: Teile deinen Beitrag in Seiten auf, jede mit eigenem Titel.','block keywordchapter'=>'Kapitel','block keywordmultipage'=>'mehrseitig','block keywordpage'=>'Seite']];